static String bumpVersion(String version, String type) {
    String[] p = version.split("\\.");
    int major = Integer.parseInt(p[0]), minor = Integer.parseInt(p[1]), patch = Integer.parseInt(p[2]);
    return switch (type) {
        case "major" -> (major+1) + ".0.0";
        case "minor" -> major + "." + (minor+1) + ".0";
        case "patch" -> major + "." + minor + "." + (patch+1);
        default -> version;
    };
}
System.out.println(bumpVersion("2.5.1","minor"));

