record SecretRecord(String name, LocalDate lastRotated) {}
static List<SecretRecord> findSecretsNeedingRotation(List<SecretRecord> secrets, int maxAge) {
    return secrets.stream().filter(s -> ChronoUnit.DAYS.between(s.lastRotated(), LocalDate.now()) > maxAge).toList();
}

record Artifact(String name, LocalDate created) {}
static List<Artifact> applyRetentionPolicy(List<Artifact> artifacts, int keepLastN) {
    List<Artifact> sorted = new ArrayList<>(artifacts);
    sorted.sort(Comparator.comparing(Artifact::created).reversed());
    return sorted.size() > keepLastN ? sorted.subList(keepLastN, sorted.size()) : List.of();
}

static void detectDrift(Map<String,String> expected, Map<String,String> actual) {
    for (String k : expected.keySet()) {
        if (!actual.containsKey(k)) System.out.println("BRAKUJE: " + k);
        else if (!actual.get(k).equals(expected.get(k))) System.out.println("ROZNICA: " + k + " oczekiwano=" + expected.get(k) + " faktycznie=" + actual.get(k));
    }
    for (String k : actual.keySet()) if (!expected.containsKey(k)) System.out.println("DODATKOWY: " + k);
}

