static void scanForHardcodedSecrets(String content) {
    Pattern pwd = Pattern.compile("password\\s*=\\s*[\"'][^\"']+[\"']", Pattern.CASE_INSENSITIVE);
    Pattern key = Pattern.compile("api[_-]?key\\s*=\\s*[\"'][^\"']+[\"']", Pattern.CASE_INSENSITIVE);
    for (String line : content.lines().toList()) {
        if (pwd.matcher(line).find() || key.matcher(line).find()) System.out.println("PODEJRZANE: " + line);
    }
}
