static void validateReleaseReadiness(boolean noSnapshot, boolean testsPass, boolean changelogUpdated, boolean coverageOk, boolean noSecrets) {
    List<String> failed = new ArrayList<>();
    if (!noSnapshot) failed.add("wersja bez -SNAPSHOT");
    if (!testsPass) failed.add("wszystkie testy przechodza");
    if (!changelogUpdated) failed.add("CHANGELOG zaktualizowany");
    if (!coverageOk) failed.add("coverage >= 80%");
    if (!noSecrets) failed.add("brak sekretow w kodzie");
    System.out.println(failed.isEmpty() ? "GOTOWY" : "NIEGOTOWY: " + failed);
}
validateReleaseReadiness(true, true, false, true, true);

